const D = { energy:.6, density:.55, scale:1, hue:28, speed:1, x:.5, y:.5, alpha:.9, relief:.6, style:'oil', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const t = K.t;
const drift = 0.9*Math.sin(t*0.61) + 0.5*Math.sin(t*1.43+1.7) + 0.32*Math.sin(t*2.29);
const swell = (K.swell!=null ? K.swell : 0.5+0.5*Math.sin(t*0.4));

const st = P.style;
const key = width+'x'+height+'|'+P.seed+'|'+st+'|'+Math.round(P.hue)+'|'+Math.round(P.density*20)+'|'+Math.round(P.scale*10);
const BW = Math.max(360, Math.min(680, Math.round(width/2.4)));
const BH = Math.max(120, Math.round(BW*height/width));

if (!S.buf || S.key !== key){
  S.key = key;
  const g = createGraphics(BW, BH); g.colorMode(HSB,360,100,100,100); g.noStroke();
  const h = createGraphics(BW, BH); h.colorMode(HSB,360,100,100,100); h.noStroke(); // ridge sheen
  const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7 + i*i*0.017)*43758.5453; return s - Math.floor(s); };
  // tonal ground: soft warm/cool gradient blobs (mid-key)
  let base, mono=false, hard=false, flow=false;
  if (st==='gouache'){ base=[P.hue,30,66]; }
  else if (st==='vangogh'){ base=[(P.hue+18)%360,58,60]; flow=true; }
  else if (st==='monochrome'){ base=[38,10,58]; mono=true; }
  else if (st==='knife'){ base=[P.hue,42,60]; hard=true; }
  else { base=[P.hue,48,58]; } // oil
  g.background(base[0], base[1]*0.7, base[2]*0.72);
  g.blendMode(BLEND);
  for (let i=0;i<26;i++){
    const bx=fr(i*3+1)*BW, by=fr(i*3+2)*BH, br=(0.14+0.5*fr(i*3+3))*BW;
    const hh = mono?base[0]:(base[0]+ (fr(i+9)-0.5)*70)%360;
    const ss = mono? 8+18*fr(i+2) : base[1]*(0.5+0.8*fr(i+4));
    const bb = base[2]*(0.6+0.7*fr(i+5));
    g.fill((hh+360)%360, Math.min(90,ss), Math.min(96,bb), 26);
    g.ellipse(bx,by,br,br);
  }
  // impasto strokes over the ground (baked)
  const N = Math.round((160 + 520*P.density) * (BW*BH)/(520*300));
  const sl = (0.02+0.05*P.scale)*BW;               // stroke length base
  for (let i=0;i<N;i++){
    const sx=fr(i*5+11)*BW, sy=fr(i*5+12)*BH;
    let ang;
    if (flow){ ang = Math.sin(sx*0.02)*1.4 + Math.cos(sy*0.017)*1.4; }
    else ang = fr(i*5+13)*Math.PI*2;
    const len = sl*(0.5+1.1*fr(i*5+14));
    const wdt = len*(hard?0.5:0.24)*(0.7+0.6*fr(i*5+15));
    // sample local ground colour, push it and paint an opaque stroke
    const hh = mono? base[0] : (base[0] + (fr(i+3)-0.5)*(st==='vangogh'?110:64) + 360)%360;
    const ss = mono? 6+16*fr(i+7) : Math.min(92, base[1]*(0.55+0.9*fr(i+8)));
    const bb = Math.min(96, base[2]*(0.5+0.95*fr(i+6)));
    g.push(); g.translate(sx,sy); g.rotate(ang);
    // body
    g.fill((hh+360)%360, ss, bb, 90);
    if (hard){ g.rectMode(CENTER); g.rect(0,0,len,wdt); }
    else { g.ellipse(0,0,len,wdt); }
    // dark valley on one flank
    g.fill((hh+360)%360, Math.min(95,ss+12), bb*0.5, 55);
    g.ellipse(0, wdt*0.32, len*0.92, wdt*0.5);
    g.pop();
    // ridge sheen line into h (bright center) for raking light
    h.push(); h.translate(sx,sy); h.rotate(ang);
    h.fill(0,0,100, 60);
    h.ellipse(0,-wdt*0.16, len*0.8, Math.max(1.2, wdt*0.22));
    h.pop();
  }
  S.buf = g; S.sheen = h;
}

const u2 = P.alpha;
push();
imageMode(CORNER);
// base paint field (opaque -> carries luminance)
blendMode(BLEND); tint(0,0,100, 100*u2);
image(S.buf, 0, 0, width, height);
noTint();

// static sheen (texture reads)
blendMode(ADD); tint(0,0,100, (22+30*P.energy)*u2);
image(S.sheen, 0, 0, width, height);
noTint();

// MOVING raking light band (the impasto signature + motion carrier)
const rlAng = 0.6 + 0.5*Math.sin(t*0.05) + 0.2*drift;   // slow light direction
const dx = Math.cos(rlAng), dy = Math.sin(rlAng);
const march = (t*0.06*P.speed + 0.15*drift);
const phase = (march % 1 + 1) % 1;
const bandC = (phase*1.6-0.3);                          // sweep center along -1..1 axis
noStroke();
blendMode(ADD);
const lc = st==='monochrome' ? [40,8] : [ (P.hue+40)%360, 26 ];
for (let s=0;s<3;s++){
  const off = bandC + (s-1)*0.16;
  const bx = width*0.5 + dx*off*width*0.7;
  const by = height*0.5 + dy*off*height*0.7;
  fill(lc[0], lc[1], 100, (18+34*P.energy)*(0.7+0.4*swell)*u2*(1-Math.abs(s-1)*0.3));
  push(); translate(bx,by); rotate(rlAng+Math.PI/2);
  ellipse(0,0, Math.max(width,height)*1.5, u*(0.16+0.1*P.relief));
  pop();
}
// trailing relief shadow (MULTIPLY) for depth
blendMode(MULTIPLY);
const sbx = width*0.5 - dx*(bandC+0.2)*width*0.7;
const sby = height*0.5 - dy*(bandC+0.2)*height*0.7;
fill(230, 30, 100-58*P.relief, (30+30*P.energy)*u2);
push(); translate(sbx,sby); rotate(rlAng+Math.PI/2);
ellipse(0,0, Math.max(width,height)*1.5, u*(0.13+0.1*P.relief));
pop();

pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
